// Build the request for OUR ffmpeg assemble endpoint (Railway). The server
// measures each clip itself and silence-pads every voiceover to its scene's
// exact video length; aspect picks the output canvas.
const clips = $('Prepare Clips').all();
if (!clips.length) throw new Error('No clips to assemble.');
const scenes = clips.map(c => ({
  videoUrl: c.json.url,
  audioUrl: (c.json.voiceUrl && c.json.voiceUrl.startsWith('http')) ? c.json.voiceUrl : undefined,
}));
const sceneChapters = clips.map(c => c.json.chapter || 0);

// Aspect resolution order: trigger input -> webhook body -> project field
// -> 16:9. Reading a nonexistent Airtable field is safely undefined.
let trig = {};
try { if ($('Receive Project ID').isExecuted) trig = $('Receive Project ID').first().json; } catch (e) {}
try { if (!trig.Aspect && $('Normalize Assemble Input').isExecuted) trig = $('Normalize Assemble Input').first().json; } catch (e) {}
const pf = ($('Fetch Project Info').first().json.fields) || {};
const aspect = (trig.Aspect === '9:16' || pf['Format'] === '9:16') ? '9:16' : '16:9';

let opts = {};
try { opts = JSON.parse(pf['Editing Options'] || '{}') || {}; } catch (e) {}

// TWO independent switches, both sent explicitly — the server's implicit
// defaults must never decide this.
//
// sfx: the Scene Final URL clips are RAW Veo output, so their audio track is
// Veo's generated ambience (the submit prompt bans speech and music, leaving
// natural sound effects only). ON → mixed at SFX_LEVEL under the narration,
// sidechain-ducked server-side so narration stays predominant. Default ON:
// silent footage under a voice sounds dead.
//
// SFX_LEVEL was 0.25 and judged too subtle on a real SFX-only render
// (Warhammer, 2026-08-10) — audible only in headphones, in the gaps. 0.35
// lifts the effects without touching the ducking, so the voice still wins
// whenever it speaks. Tune HERE; the server's own default is never used.
const SFX_LEVEL = 0.35;
const sfxOn = opts.sfx !== false;

// music: a background track from the Drive 'Muzica' folder AND the
// synthesized boom/whoosh/riser accents at hook, chapter cuts and end
// screen. Neither comes from the scene — both are composed here — so they
// share one opt-IN switch. The accents used to play unconditionally, which
// is how a film ended up carrying music unrelated to its footage.
const musicOn = opts.music === true;
let musicUrl;
if (musicOn) {
  try { musicUrl = $('Pick Music Track').first().json.url || undefined; } catch (e) {}
}

return [{ json: { body: {
  scenes,
  sceneChapters,
  musicUrl,
  aspect,
  nativeAudio: sfxOn ? SFX_LEVEL : false,
  stingers: musicOn,
}, sceneCount: scenes.length, tone: pf.Tonalitate || 'default', aspect, musicUrl: musicUrl || null, sfx: sfxOn, sfxLevel: sfxOn ? SFX_LEVEL : 0, music: musicOn } }];

const j = $input.first().json;
// A mid-render Railway deploy replaces the container and wipes the
// in-memory job map: the poll answers 404 'job not found' although nothing
// was wrong with the job. The work died with the container, so the only
// recovery is resubmitting — flagged here, routed by 'Render Lost?'.
const httpErr = j.error && typeof j.error === 'object' ? String(j.error.message || j.error.description || '') : (typeof j.error === 'string' && !j.status ? j.error : '');
// 180 polls x 5s = 15 minutes, the SAME ceiling this loop always had. The
// interval came down from 20s because 'Wait Render' sleeps BEFORE the first
// check: measured on execution 3599, ffmpeg had finished a one-scene film
// well inside the first 20s and n8n slept all of it. Any change to the Wait
// node has to move this number by the same factor or the ceiling moves with
// it — at 5s the old cap of 45 would time out after 3m45s and kill every
// long assemble.
const MAX_POLLS = 180;
if (/not.*found|404/i.test(httpErr)) {
  if ($runIndex > MAX_POLLS) throw new Error('assemble job lost repeatedly (' + $runIndex + ' polls) — giving up.');
  return [{ json: { lost: true, status: 'lost' } }];
}
const s = (j.status || '').toLowerCase();
if (s === 'error') {
  throw new Error('assemble failed: ' + (j.error || 'unknown'));
}
if ($runIndex > MAX_POLLS) {
  throw new Error('assemble timed out after ' + $runIndex + ' polls. Last status: ' + s);
}
return [{ json: Object.assign({ lost: false }, j) }];

let scenes = $input.all().slice();
const seen = new Set();
scenes = scenes.filter(s => { const id = s.json.id; if (!id || seen.has(id)) return false; seen.add(id); return true; });
scenes = scenes.filter(s => { const v = (s.json.fields || {})['Scene Final URL'] || ''; return v.startsWith('http'); });
const ord = it => { const f = it.json.fields || {}; return (typeof f['Ordine Scenă'] === 'number') ? f['Ordine Scenă'] : null; };
scenes.sort((a, b) => {
  const oa = ord(a), ob = ord(b);
  if (oa !== null && ob !== null && oa !== ob) return oa - ob;
  const t = new Date(a.json.createdTime) - new Date(b.json.createdTime);
  if (t) return t;
  return a.json.id < b.json.id ? -1 : 1;
});
if (!scenes.length) throw new Error('No scenes with a final muxed clip (Scene Final URL) found for this project.');
return scenes.map((s, i) => {
  const o = ord(s);
  // Ordine Scenă = chapter*100 + scene (hook = 1 → chapter 0).
  const chapter = o !== null ? Math.floor(o / 100) : (i === 0 ? 0 : 1);
  return { json: {
    id: s.json.id,
    url: s.json.fields['Scene Final URL'],
    voiceUrl: s.json.fields['Voiceover URL'] || '',
    // Same strip as both TTS paths: speaker tags ([NARRATOR], [CHARACTER: X])
    // are routing, not narration — without this they showed up in captions.
    narratorText: String(s.json.fields['Script Scenă'] || '').replace(/\[[^\]]{0,60}\]\s*/g, ' ').replace(/\s+/g, ' ').trim(),
    chapter,
  } };
});

// Website/manual retrigger path: accept {Project_ID, aspect?, captions?} in
// the POST body and hand downstream the same shape the sub-workflow trigger
// gives.
const b = $json.body || {};
const id = b.Project_ID || b.project_id || '';
if (!id) throw new Error('Project_ID missing in webhook body');
return [{ json: {
  Project_ID: id,
  Aspect: b.aspect === '9:16' ? '9:16' : (b.aspect || ''),
  No_Captions: (b.captions === 'no' || b.no_captions === true) ? 'yes' : '',
} }];

// Diagnostic harness (draft only): route a metadata or compose request
// through the existing fal-credentialed nodes.
const b = $json.body || {};
if (b.mode === 'compose') return [{ json: { body: b.compose } }];
return [{ json: { url: b.media_url } }];

const driveId = $('Upload Final To Drive').first().json.id;
return [{ json: {
  video_url: 'https://drive.google.com/uc?export=download&id=' + driveId,
  verify: $('Render Guard').last().json.verify || null,
} }];

// Graphics pass: hook title, chapter markers, transitions, captions,
// grade and end screen over the ffmpeg-assembled video. Scene timings and
// real narration lengths come from the assemble step's own ffprobe
// verification, so captions pace with the actual voice.
const status = $('Render Guard').last().json; // {outputUrl, verify}
if (!status.outputUrl) throw new Error('assemble outputUrl missing');
const clips = $('Prepare Clips').all();
const v = status.verify || {};
const starts = v.sceneStartsSeconds || [];
const voices = v.voiceDurationsSeconds || [];
const total = v.videoSeconds || 0;
const scenes = clips.map((c, i) => {
  const start = starts[i] ?? (i * 8);
  const end = (i + 1 < starts.length) ? starts[i + 1] : total;
  return {
    narratorText: c.json.narratorText || '',
    startSeconds: start,
    durationSeconds: Math.max(0.5, end - start),
    chapter: c.json.chapter || 0,
    speechSeconds: voices[i] || undefined,
  };
});
const pf = $('Fetch Project Info').first().json.fields || {};

// Aspect + captions: trigger input -> webhook body -> project fields -> defaults.
let trig = {};
try { if ($('Receive Project ID').isExecuted) trig = $('Receive Project ID').first().json; } catch (e) {}
try { if (!trig.Aspect && !trig.No_Captions && $('Normalize Assemble Input').isExecuted) trig = $('Normalize Assemble Input').first().json; } catch (e) {}
const aspectRatio = (trig.Aspect === '9:16' || pf['Format'] === '9:16') ? '9:16' : '16:9';

// Per-overlay toggles chosen in the site form, stored as JSON on the
// project ('Editing Options'). Missing field/old projects = everything on.
let opts = {};
try { opts = JSON.parse(pf['Editing Options'] || '{}') || {}; } catch (e) { opts = {}; }

// How hard the montage re-frames across a cut. 0 holds ONE framing for the
// whole film; 1 and 2 contrast the framing at every scene boundary.
//
// Sent explicitly, and defaulting to 0, because omitting it made Remotion
// derive it from the tone's editing energy - which is 1 for most tones, so
// every film got the contrast whether it suited the footage or not. Measured
// on a 15-scene dialogue film: scale jumps of 0.075 to 0.135 plus a position
// shift, on all 14 boundaries. The planner is blind to the footage, and the
// contrast only reads as a new shot when consecutive scenes actually look
// different. On a two-hander every scene is the same two people in the same
// place, so it reads as a zoom of the same shot - reported three times as a
// zoom bug, and it was never a bug, it was this setting.
//
// Still a button, not a decision: a project that wants the contrast back sets
// montageIntensity in its Editing Options.
const montageIntensity = [0, 1, 2].includes(opts.montageIntensity) ? opts.montageIntensity : 0;

// A cinematic (silent) project's Script Scenă is an unspoken shot note, not
// narration. THREE surfaces read that field as if it were spoken, and each
// one puts the beat sheet on screen: captions print it, the chapter card
// borrows its first eight words when the chapter has no title of its own,
// and a text card lifts figures out of it (a year or a duration in a stage
// direction reads to the pattern exactly like a fact the narration speaks).
// Captions were the only one visible to the producer, which is how the other
// two survived. One flag now tells the render, and all three read it.
const narrationIsSpoken = opts.category !== 'cinematic';
const showCaptions = !(trig.No_Captions === 'yes' || pf['Fără Subtitrări'] === true) && narrationIsSpoken;

// Real chapter titles from the linked script's [CHAPTER n: title] markers.
const chapterTitles = {};
try {
  const sc = ($('Fetch Script Titles').first().json.fields || {})['Script Content'] || '';
  const re = /\[CHAPTER\s+(\d+)\s*:\s*([^\]]+)\]/g;
  let m;
  while ((m = re.exec(sc))) chapterTitles[m[1]] = m[2].trim();
} catch (e) {}

return [{ json: { body: {
  finalVideoUrl: status.outputUrl,
  projectTitle: pf['Nume Proiect'] || 'Video Factory',
  scenes,
  tone: pf['Tonalitate'] || 'Dark',
  channelName: 'Video Factory',
  aspectRatio,
  showCaptions,
  narrationIsSpoken,
  montageIntensity,
  showHookTitle: opts.hookTitle !== false,
  showChapterCards: opts.chapterCards !== false,
  showEndScreen: opts.endScreen !== false,
  chapterTitles,
} } }];

const j = $input.first().json;
// Same deploy-wipes-the-job recovery as Render Guard: 404 from the status
// poll means the container restarted mid-render, not that the render broke.
const httpErr = j.error && typeof j.error === 'object' ? String(j.error.message || j.error.description || '') : (typeof j.error === 'string' && !j.status ? j.error : '');
// First render also bundles the project, and Chromium renders take minutes,
// not seconds — allow up to ~30 min before declaring a hang. 360 polls x 5s
// is exactly the ceiling the old 90 x 20s gave; the interval came down so a
// finished render is noticed within 5s instead of up to 20. Move the Wait
// node and this number moves with it, or the ceiling silently shrinks.
const MAX_POLLS = 360;
if (/not.*found|404/i.test(httpErr)) {
  if ($runIndex > MAX_POLLS) throw new Error('graphics job lost repeatedly (' + $runIndex + ' polls) — giving up.');
  return [{ json: { lost: true, status: 'lost' } }];
}
const s = (j.status || '').toLowerCase();
if (s === 'error') throw new Error('Remotion render failed: ' + (j.error || 'unknown'));
if ($runIndex > MAX_POLLS) throw new Error('Remotion render timed out after ' + $runIndex + ' polls. Last status: ' + s + ' progress: ' + (j.progress || 0));
return [{ json: Object.assign({ lost: false }, j) }];

// Track selection order:
//   1. files inside the tone-matched subfolder (Muzica/Dark, Muzica/Default...)
//   2. loose files in Muzica whose NAME contains the tone (dark-1.mp3)
//   3. loose files named default*
//   4. any loose file
// Multiple candidates -> random pick, so repeat videos vary.
const norm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const isFile = (f) => f && f.id && !(f.mimeType || '').includes('folder');
let tone = 'default';
try { tone = norm($('Fetch Project Info').first().json.fields.Tonalitate); } catch (e) {}
let subFiles = [];
try { subFiles = ($input.first().json.files || []).filter(isFile); } catch (e) {}
let rootFiles = [];
try { rootFiles = ($('List Music').first().json.files || []).filter(isFile); } catch (e) {}
const byTone = rootFiles.filter(f => norm(f.name).includes(tone));
const byDefault = rootFiles.filter(f => norm(f.name).includes('default'));
const pool = subFiles.length ? subFiles : (byTone.length ? byTone : (byDefault.length ? byDefault : rootFiles));
if (!pool.length) return [{ json: { url: null, name: null, reason: 'no tracks in Muzica folder' } }];
const t = pool[Math.floor(Math.random() * pool.length)];
// Served through our Railway media proxy so ffmpeg gets a real audio
// stream (Drive's direct links answer with redirects/HTML).
return [{ json: { id: t.id, name: t.name, matched: subFiles.length ? 'subfolder' : (byTone.length ? 'tone-name' : (byDefault.length ? 'default' : 'any')), url: 'https://n8n-production-55dd.up.railway.app/media?id=' + t.id } }];

// Subfolder-per-tone layout: Muzica/Dark, Muzica/Epic, ... If a subfolder
// matches the project's Tonalitate (or 'Default' as fallback), its files
// are preferred over loose files in the root.
const norm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
let tone = 'default';
try { tone = norm($('Fetch Project Info').first().json.fields.Tonalitate); } catch (e) {}
let folders = [];
try { folders = ($input.first().json.files || []).filter(f => (f.mimeType || '').includes('folder')); } catch (e) {}
const hit = folders.find(f => norm(f.name).includes(tone)) || folders.find(f => norm(f.name).includes('default')) || null;
return [{ json: { folderId: hit ? hit.id : null, folderName: hit ? hit.name : null } }];

// Motif cards chosen by Claude Scripting and validated THERE, where the whole
// story was known and a quote could still be checked against its scene. This
// is a lookup: nothing is re-judged on the render path.
const body = $json.body;

let opts = {};
try {
  opts = JSON.parse(($('Fetch Project Info').first().json.fields || {})['Editing Options'] || '{}') || {};
} catch (e) { opts = {}; }
const cards = Array.isArray(opts.motifCards) ? opts.motifCards : [];

if (cards.length) {
  // Ordine Scenă per scene id, from the node that still has both.
  const orderById = new Map();
  try {
    for (const it of $('Fetch Approved Scenes').all()) {
      const f = it.json.fields || {};
      if (it.json.id != null) orderById.set(it.json.id, f['Ordine Scenă']);
    }
  } catch (e) {}
  // The rendered scene list, in its own order, expressed as those numbers.
  const rendered = $('Prepare Clips').all().map((c) => orderById.get(c.json.id));

  const out = [];
  for (const card of cards) {
    const i = (card.sceneOrder !== undefined && card.sceneOrder !== null)
      ? rendered.indexOf(card.sceneOrder)
      : card.sceneIndex;
    // A card whose scene never got a clip is left out. Not a failure to
    // report: the scene is not in the film either.
    if (!(i >= 0 && i < (body.scenes || []).length)) continue;
    const spec = Object.assign({}, card);
    // Bookkeeping for the producer's panel, not for the renderer.
    delete spec.sceneOrder;
    delete spec.verdict;
    delete spec.why;
    spec.sceneIndex = i;
    out.push(spec);
  }
  // Only when there is one: an empty array still counts as "explicit cards"
  // downstream and would switch the derived ones off for nothing.
  if (out.length) body.textCards = out;
}

return [{ json: { body } }];
